-- c003-v011: جلدی–کرو اور–آؤ سب– قوموں چاروں–طرف–سے اور–جمع–ہو وہاں اُتار یہوواہ اپنے–بہادروں–کو
-- c003-v012: جاگیں اور–آئیں قومیں طرف– وادی یہوسفط–کی کیونکہ وہاں بیٹھوں–گا عدالت–کرنے–کو کو– سب– قوموں چاروں–طرف–سے
-- c003-v013: چلاؤ درانتی کیونکہ پک–گئی فصل آؤ اُترو کیونکہ– بھر–گیا حوض اُبل–پڑتے–ہیں کُنڈ کیونکہ بہت–ہے اُن–کی–بدی
-- c003-v014: ہجوم ہجوم وادی–میں فیصلے–کی کیونکہ قریب–ہے دن یہوواہ–کا وادی–میں فیصلے–کی
-- c003-v015: سورج اور–چاند سیاہ–ہو–جاتے–ہیں اور–ستارے سمیٹ–لیتے–ہیں اپنی–چمک
-- c003-v016: اور–یہوواہ صیون–سے دہاڑے–گا اور–یروشلم–سے دے–گا اپنی–آواز اور–لرزیں–گے آسمان اور–زمین اور–یہوواہ پناہ–ہے اپنی–قوم–کے–لیے اور–قلعہ–ہے بنی اسرائیل–کے–لیے
-- c003-v017: اور–جان–لو–گے کہ میں یہوواہ تمہارا–خدا–ہوں رہنے–والا صیون–میں پہاڑ– میرے–مقدس اور–ہوگی یروشلم مقدس اور–اجنبی نہیں– گزریں–گے– اُس–میں–سے پھر [فاصلہ]
-- c003-v018: اور–ہوگا اُس–دن اُس ٹپکیں–گے پہاڑ میٹھی–مے اور–پہاڑیاں بہیں–گی دودھ–سے اور–سب– ندیاں یہوداہ–کی بہیں–گی پانی–سے اور–چشمہ گھر–سے– یہوواہ–کے نکلے–گا اور–سیراب–کرے–گا کو– وادی شطیم–کی
-- c003-v019: مصر ویرانی ہوگا اور–ادوم بیابان ویران ہوگا ظلم–کی–وجہ–سے بنی یہوداہ–پر جنہوں–نے– بہایا خون– بے–گناہ اُن–کی–زمین–میں
-- c003-v020: اور–یہوداہ ہمیشہ–تک آباد–رہے–گا اور–یروشلم نسل–در نسل
-- c003-v021: اور–پاک–کروں–گا اُن–کا–خون نہیں– پاک–کیا–تھا اور–یہوواہ رہتا–ہے صیون–میں

